//! Node.js bindings for the Fieldglass readers, generated by napi-rs.
//!
//! A binding layer and nothing more: every type here converts a value from the
//! `fieldglass` umbrella into something the JS boundary can carry, and every
//! function is a thin call through. Decode, projection and paint logic belongs
//! below the umbrella, never in this crate (ADR-0006) — and the umbrella is the
//! only workspace crate this one names (#574).

use fieldglass::netcdf::{
    DatasetView, Hdf5Attribute, Hdf5Metadata, NetcdfBacking, NetcdfReader, RenderableVariable,
    extract_plane,
};
use fieldglass::render::{Projected, ResolvedOptions};
use fieldglass::{
    Format, GridGeometry, ProjectedPolylines, Scan, SpatialIndex, detect_from_bytes,
    normalize_units,
};
use napi_derive::napi;
use std::sync::Mutex;

// The characterisation golden for render, probe, contours and CSV (#570). Test
// only: it replays the display path over the committed fixture corpus.
#[cfg(test)]
mod characterisation;
mod directory_store;

// This host, run through the ADR-0006 conformance suite that ships in
// `fieldglass` (#573). Test only, and the second runner of one set of
// expectations — the browser host's Node runner is the third.
#[cfg(test)]
mod conformance_host;

/// Bridge a foreign crate's error into a [`napi::Error`] by its `Display` text.
///
/// `impl From<FieldglassError> for napi::Error` is what this would rather be,
/// but the orphan rule forbids it: both types are foreign to this crate. An
/// extension trait on `Result` is the local equivalent, and it collapses the
/// `map_err` closure that every reader and decoder call otherwise repeats
/// verbatim.
///
/// The blanket impl is bound only on `Display`, which `napi::Error` itself
/// satisfies — so `.into_napi()` compiles on a `napi::Result` too, and there it
/// is wrong: it re-wraps the reason and drops the original `napi::Status` to
/// `GenericFailure`. A `napi::Result` needs no bridging; use `?` on it.
trait IntoNapi<T> {
    /// Map the error side to a [`napi::Error`] carrying its `Display` text.
    fn into_napi(self) -> napi::Result<T>;
}

impl<T, E: std::fmt::Display> IntoNapi<T> for Result<T, E> {
    fn into_napi(self) -> napi::Result<T> {
        self.map_err(|e| napi::Error::from_reason(e.to_string()))
    }
}

#[cfg(test)]
mod into_napi_tests {
    use super::IntoNapi;
    use fieldglass::FieldglassError;

    /// The reason is the error's own `Display`, verbatim and unprefixed. Every
    /// reader-construction and decode failure the hosts surface is bridged
    /// here, so giving the helper a context prefix would re-word all fifteen
    /// messages at once — this is the test that would catch that.
    #[test]
    fn the_reason_is_the_display_text_verbatim() {
        let failed: Result<(), _> = Err(FieldglassError::UnsupportedSection("5.61".into()));
        assert_eq!(
            failed.into_napi().unwrap_err().reason,
            "unsupported section: 5.61"
        );
    }

    /// The success side is a pass-through: the bridge touches only `Err`.
    #[test]
    fn an_ok_survives_the_bridge_unchanged() {
        let decoded: Result<u32, FieldglassError> = Ok(7);
        assert_eq!(decoded.into_napi().unwrap(), 7);
    }
}

/// A message resolved for a feature: its values and where they sit. Spectral
/// messages resolve to the synthesized global lat/lon grid, everything else to
/// its declared grid (#330).
type ResolvedField = (std::sync::Arc<Vec<Option<f64>>>, Placed);

/// Map an eccodes-style `packingType` (GRIB1) or §5 template name (GRIB2) to a
/// friendly label for the message table. Falls back to the raw identifier for
/// anything unmapped so a new variant still shows *something* meaningful.
fn friendly_packing(label: &str) -> String {
    let mapped = match label {
        "grid_simple" | "simple" => "Simple grid-point",
        "grid_complex" | "complex" => "Complex packing",
        "grid_complex_spatial_differencing" | "complex_spatial_diff" => {
            "Complex packing + spatial differencing"
        }
        "grid_ieee" | "ieee" => "IEEE float",
        "grid_jpeg" | "jpeg" => "JPEG 2000",
        "grid_png" | "png" => "PNG",
        "grid_ccsds" | "ccsds" => "CCSDS",
        "grid_run_length" | "run_length" => "Run-length",
        "grid_simple_log_preprocessing" | "simple_log_preprocessing" => "Simple packing (log)",
        "spectral_simple" | "spectral_complex" => "Spectral (spherical harmonic)",
        "bifourier_complex" => "Bi-Fourier (spectral)",
        "grid_simple_matrix" => "Matrix of values",
        "second_order" => "Second-order",
        "grid_second_order" => "Second-order (SPD-2)",
        "grid_second_order_no_SPD" => "Second-order (no SPD)",
        "grid_second_order_SPD1" => "Second-order (SPD-1)",
        "grid_second_order_SPD3" => "Second-order (SPD-3)",
        "grid_second_order_row_by_row" => "Second-order (row-by-row)",
        "grid_second_order_constant_width" => "Second-order (constant width)",
        "grid_second_order_general_grib1" => "Second-order (general)",
        "grid_second_order_unknown" => "Second-order",
        "spectral" => "Spherical harmonic",
        // GRIB2 unsupported(5.N) templates: name the scheme behind the number.
        other => {
            if let Some(n) = other
                .strip_prefix("unsupported(5.")
                .and_then(|s| s.strip_suffix(')'))
            {
                return match n {
                    "2" | "3" => format!("Complex packing (5.{n})"),
                    "40" => "JPEG 2000 (5.40)".to_string(),
                    "41" => "PNG (5.41)".to_string(),
                    "42" => "CCSDS (5.42)".to_string(),
                    _ => format!("Unsupported (5.{n})"),
                };
            }
            return other.to_string();
        }
    };
    mapped.to_string()
}

/// The message table's label for a packing identifier — `MessageInfo.packing`,
/// e.g. `"grid_second_order"` — such as `"Second-order (SPD-2)"`. An identifier
/// with no label comes back as itself, so a new packing still shows something.
///
/// A function rather than a field because the label is this host's display
/// text and lossy on purpose (#727), where `MessageInfo.packing` is the
/// identifier both hosts report (#574).
#[napi]
pub fn packing_label(packing: String) -> String {
    friendly_packing(&packing)
}

/// An API DTO in the shape it crosses to JavaScript: the plain object its
/// serde form describes (ADR-0006 decision 2).
///
/// **Every key is present, and a Rust `None` is `null`** (#574, decided
/// 2026-09-29). That is what `serde_json` writes for an `Option` field, and
/// nothing here strips nulls. The declaration a caller reads is generated from
/// the same schema (`extension/src/api.generated.ts`), and the extension's
/// `api-wire` test checks real values against it.
///
/// Two things `serde_json` does that the browser binding does not, and why
/// neither reaches a DTO this returns:
///
/// - A non-finite float becomes `null`, where the browser passes `NaN`. No
///   field of `AxisValues` can hold one, because a coordinate that is not finite
///   is a hole and the axis reports none (`fieldglass::Session::axis_values`).
///   No field of `MessageInfo` does either. Its floats are all in its grid,
///   and the grid's parameters are GRIB integers scaled, IBM floats (GRIB1,
///   which cannot encode a NaN or an infinity), or GRIB2 IEEE floats, §3.1's
///   angle of rotation and §3.12's scale factor, a non-finite one of which
///   declines the grid rather than building it (#823); and `core` withholds an
///   origin or extent it cannot compute rather than returning one.
///   `no_message_carries_a_non_finite_float` holds that over every committed
///   GRIB message, and
///   `a_non_finite_grid_parameter_crosses_as_the_session_holds_it` over the two
///   IEEE parameters set to NaN and both infinities.
/// - An integer above 2^53 becomes a `BigInt`. The byte offsets and lengths of
///   any GRIB file this can hold in memory are far below it.
fn to_js(dto: Result<serde_json::Value, serde_json::Error>) -> napi::Result<serde_json::Value> {
    dto.map_err(|e| napi::Error::from_reason(e.to_string()))
}

/// Detect the format of a file from its raw bytes.
/// Returns "grib1" | "grib2" | "netcdf" | "unknown".
#[napi]
pub fn detect_bytes(bytes: napi::bindgen_prelude::Buffer) -> String {
    match detect_from_bytes(&bytes) {
        Format::Grib1 => "grib1".to_string(),
        Format::Grib2 => "grib2".to_string(),
        Format::NetCdf => "netcdf".to_string(),
        Format::Unknown => "unknown".to_string(),
    }
}

// ---------------------------------------------------------------------------
// NetCDF
// ---------------------------------------------------------------------------

/// One NetCDF dimension, flattened for the JS boundary.
#[napi(object)]
#[derive(Debug)]
pub struct DimensionMeta {
    /// The dimension's name as the file declares it.
    pub name: String,
    /// Length of the dimension. `0` is a valid display value for the
    /// unlimited / record dimension (with `is_record == true`).
    pub length: f64,
    /// Whether this is the unlimited (record) dimension. Exactly one classic
    /// file dimension may be, and its `length` is the file's record count.
    pub is_record: bool,
}

/// One NetCDF attribute (global or per-variable). `value` is already a
/// human-readable string — UTF-8 for Char attributes, comma-separated decimal
/// for numeric ones — so the provider can render it as-is.
#[napi(object)]
#[derive(Debug)]
pub struct AttributeMeta {
    /// The attribute's name as the file declares it.
    pub name: String,
    /// The attribute's declared element type, e.g. `"char"`, `"float"`.
    pub nc_type: String,
    /// The attribute's value, already rendered for display — see the type doc.
    pub value: String,
}

/// One NetCDF variable, flattened for the JS boundary. `dimensions` lists
/// resolved dimension names (in declared order) so the provider doesn't need
/// to cross-reference dim ids itself.
// `use_nullable` so `units` crosses as `null`, not as a missing key (#574).
#[napi(object, use_nullable = true)]
#[derive(Debug)]
pub struct VariableMeta {
    /// The variable's name as the file declares it.
    pub name: String,
    /// The variable's declared element type, e.g. `"short"`, `"double"`.
    pub nc_type: String,
    /// Names of the variable's dimensions, in declared (C) order — slowest
    /// varying first.
    pub dimensions: Vec<String>,
    /// The variable's CF `units`, typeset for display the way a GRIB unit is
    /// (ADR-0007). `null` when the variable declares none (#775).
    ///
    /// Lifted out of `attributes` because the metadata view has no room to
    /// print them all: it previews the first three and hides the rest behind
    /// "+N more", and `units` is routinely past that cut (in OISST it is the
    /// fifth attribute on every field). Units were reachable only by rendering
    /// the variable, which is not where a reader looks for them. Normalised
    /// here rather than in the view so the table and the render panel cannot
    /// print the same units two different ways.
    pub units: Option<String>,
    /// Every attribute on the variable, in file order, `units` included.
    pub attributes: Vec<AttributeMeta>,
}

/// The CF `units` attribute, typeset (ADR-0007), or empty when absent.
fn units_from(attributes: &[AttributeMeta]) -> Option<String> {
    attributes
        .iter()
        .find(|a| a.name == "units")
        .map(|a| normalize_units(&a.value).into_owned())
        // After normalising, as `fieldglass`'s own seam does: an all-blank
        // attribute states no units either (#775).
        .filter(|units| !units.trim().is_empty())
}

/// Top-level NetCDF dataset metadata. Covers what's exposable from the
/// header alone; per-variable values are a separate decode step (out of
/// scope for issue #29).
///
/// Every key is present, and a field with nothing to report is `null`, never
/// missing (#574).
// `use_nullable`: napi writes `null` for a `None` and declares the field
// `T | null`, the wire form every object this addon returns has (#574, decided
// 2026-09-29). Without it the key is left out and reads `undefined`, which is
// how a `T | null` declaration once let a `!== null` guard through (#288).
#[napi(object, use_nullable = true)]
#[derive(Debug)]
pub struct DatasetMeta {
    /// `"classic"` (CDF-1/2/5) or `"hdf5"` (NetCDF-4).
    pub backing: String,
    /// Human-readable label, e.g. `"NetCDF classic (CDF-1)"` or
    /// `"NetCDF-4 / HDF5"`.
    pub backing_label: String,
    /// `true` if dimensions / variables / attributes are populated. Always
    /// `true` for classic; `true` for HDF5 once its dimension-scale metadata
    /// resolves, and `false` (with `note` set) only when an HDF5 file uses a
    /// layout outside the decoded subset.
    ///
    /// A file with an undecodable *datatype* on one variable keeps
    /// `fully_parsed = true` and names that variable in
    /// `unsupported_variables`: the tables are populated, so a host that hides
    /// them on `false` would hide everything over one variable (#550).
    pub fully_parsed: bool,
    /// Free-form note for the provider to surface when `fully_parsed` is
    /// false — e.g. why an HDF5 file's metadata could not be fully resolved.
    /// `null` otherwise.
    pub note: Option<String>,
    /// Every dimension in the file, in declared order.
    pub dimensions: Vec<DimensionMeta>,
    /// The file-level attributes, in declared order.
    pub global_attributes: Vec<AttributeMeta>,
    /// Every variable in the file, in declared order — coordinate variables
    /// included, unlike [`NetcdfHandle::variables`].
    pub variables: Vec<VariableMeta>,
    /// HDF5 superblock version, when applicable. `null` for classic files.
    pub hdf5_superblock_version: Option<i32>,
    /// NetCDF-4 datasets left out of `variables` because their HDF5 datatype is
    /// outside the decoded subset — compound, enum, variable-length, opaque or
    /// array (#550). Empty for a classic file and for a NetCDF-4 file every
    /// variable of which decoded.
    ///
    /// `fully_parsed` stays `true` when this is non-empty: the rest of the
    /// metadata *is* resolved, and a host should show it and name these
    /// alongside rather than fall back to the superblock-only view.
    pub unsupported_variables: Vec<UnsupportedVariableMeta>,
}

/// One NetCDF-4 dataset the reader declined, for [`DatasetMeta::unsupported_variables`].
#[napi(object)]
#[derive(Debug)]
pub struct UnsupportedVariableMeta {
    /// The variable's name, path-qualified when it lives in a nested group.
    pub name: String,
    /// Why it could not be described, as the decoder phrased it.
    pub reason: String,
}

/// Parse a NetCDF file from raw bytes and return the top-level dataset
/// metadata. Errors only for files that are neither classic CDF nor HDF5;
/// HDF5 files succeed with `fully_parsed = false`.
#[napi]
pub fn open_netcdf(bytes: napi::bindgen_prelude::Buffer) -> napi::Result<DatasetMeta> {
    let reader = NetcdfReader::from_bytes(bytes.to_vec()).into_napi()?;
    Ok(dataset_meta_from(&reader))
}

fn dataset_meta_from(reader: &NetcdfReader) -> DatasetMeta {
    let label = reader.backing.label().to_string();
    // HDF5 / NetCDF-4: resolve the dimension-scale convention (decision 0003) to
    // the same dimensions / variables / attributes the classic backing exposes.
    // Resolution is fallible (a layout outside the decoded subset); on failure we
    // fall back to the format-only view with the reason in `note`, so the file
    // still opens and the superblock still renders.
    if let NetcdfBacking::Hdf5(probe) = &reader.backing {
        let superblock = Some(probe.superblock_version as i32);
        return match reader.hdf5_metadata() {
            Ok(meta) => hdf5_dataset_meta(label, superblock, meta),
            Err(e) => hdf5_unparsed_meta(label, superblock, &e.to_string()),
        };
    }
    match &reader.backing {
        NetcdfBacking::Classic(h) => {
            let dim_names: Vec<String> = h.dimensions.iter().map(|d| d.name.clone()).collect();
            let dimensions = h
                .dimensions
                .iter()
                .map(|d| DimensionMeta {
                    name: d.name.clone(),
                    length: d.length as f64,
                    is_record: d.is_record,
                })
                .collect();
            let global_attributes = h
                .global_attributes
                .iter()
                .map(|a| AttributeMeta {
                    name: a.name.clone(),
                    nc_type: a.nc_type.name().to_string(),
                    value: a.value.clone(),
                })
                .collect();
            let variables = h
                .variables
                .iter()
                .map(|v| {
                    let attributes: Vec<AttributeMeta> = v
                        .attributes
                        .iter()
                        .map(|a| AttributeMeta {
                            name: a.name.clone(),
                            nc_type: a.nc_type.name().to_string(),
                            value: a.value.clone(),
                        })
                        .collect();
                    VariableMeta {
                        name: v.name.clone(),
                        nc_type: v.nc_type.name().to_string(),
                        dimensions: v
                            .dim_ids
                            .iter()
                            .map(|&id| {
                                dim_names
                                    .get(id as usize)
                                    .cloned()
                                    .unwrap_or_else(|| format!("dim#{id}"))
                            })
                            .collect(),
                        units: units_from(&attributes),
                        attributes,
                    }
                })
                .collect();
            DatasetMeta {
                backing: "classic".to_string(),
                backing_label: label,
                fully_parsed: true,
                note: None,
                dimensions,
                global_attributes,
                variables,
                hdf5_superblock_version: None,
                unsupported_variables: Vec::new(),
            }
        }
        // HDF5 is handled above, before this match is reached.
        NetcdfBacking::Hdf5(_) => unreachable!("HDF5 backing resolved before the match"),
    }
}

/// Map a resolved NetCDF-4 / HDF5 root group to the JS dataset metadata.
fn hdf5_dataset_meta(label: String, superblock: Option<i32>, meta: Hdf5Metadata) -> DatasetMeta {
    // Datasets the resolver skipped rather than failed the file for (#550).
    // They are reported next to the variables that did resolve, not instead of
    // them, which is why `fully_parsed` below stays `true`.
    let unsupported: Vec<UnsupportedVariableMeta> = meta
        .unsupported
        .into_iter()
        .map(|u| UnsupportedVariableMeta {
            name: u.name,
            reason: u.reason,
        })
        .collect();
    let dimensions = meta
        .dimensions
        .into_iter()
        .map(|d| DimensionMeta {
            name: d.name,
            length: d.length as f64,
            is_record: d.is_unlimited,
        })
        .collect();
    let variables = meta
        .variables
        .into_iter()
        .map(|v| {
            let attributes: Vec<AttributeMeta> =
                v.attributes.iter().map(hdf5_attribute_meta).collect();
            VariableMeta {
                name: v.name,
                nc_type: v.nc_type.name().to_string(),
                dimensions: v.dimensions,
                units: units_from(&attributes),
                attributes,
            }
        })
        .collect();
    DatasetMeta {
        backing: "hdf5".to_string(),
        backing_label: label,
        fully_parsed: true,
        note: None,
        dimensions,
        global_attributes: meta
            .global_attributes
            .iter()
            .map(hdf5_attribute_meta)
            .collect(),
        variables,
        hdf5_superblock_version: superblock,
        unsupported_variables: unsupported,
    }
}

/// The format-only fallback when HDF5 metadata can't be fully resolved — the
/// file still opens and reports its superblock, with the reason in `note`.
fn hdf5_unparsed_meta(label: String, superblock: Option<i32>, reason: &str) -> DatasetMeta {
    DatasetMeta {
        backing: "hdf5".to_string(),
        backing_label: label,
        fully_parsed: false,
        note: Some(format!(
            "NetCDF-4 / HDF5 metadata could not be fully resolved ({reason}); \
             only the superblock has been validated."
        )),
        dimensions: Vec::new(),
        global_attributes: Vec::new(),
        variables: Vec::new(),
        hdf5_superblock_version: superblock,
        // Nothing resolved, so there is no partial list to qualify: the note
        // above already says the whole file's metadata is unavailable.
        unsupported_variables: Vec::new(),
    }
}

fn hdf5_attribute_meta(a: &Hdf5Attribute) -> AttributeMeta {
    AttributeMeta {
        name: a.name.clone(),
        nc_type: a.datatype.nc_type.name().to_string(),
        value: a.value.clone(),
    }
}

/// Decoded values for one NetCDF variable, flattened for the JS boundary.
/// Mirrors [`DecodedGrid`] but carries the full N-D `shape` (a NetCDF variable
/// may be 1-D, 3-D, 4-D, …) instead of a single width/height.
#[napi(object)]
pub struct DecodedVariable {
    /// Row-major (C / on-disk order) values; `f64::NAN` at masked / fill
    /// positions (read `mask` to distinguish a real value from a fill).
    pub values: napi::bindgen_prelude::Float64Array,
    /// Parallel to `values`: `1` present, `0` equal to the variable's
    /// `_FillValue`.
    pub mask: napi::bindgen_prelude::Buffer,
    /// Dimension lengths in declared (C) order; the unlimited dimension
    /// contributes the file's record count.
    pub shape: Vec<u32>,
}

/// Decode one NetCDF variable's values by index. Works for classic (CDF-1/2/5)
/// and NetCDF-4 / HDF5 backings; for HDF5 a "variable" is a root-group dataset
/// in name-sorted order. Errors for `char` / string variables (text, not
/// numbers), datasets stored with a layout not yet decoded (e.g. a version-4
/// chunk index), and out-of-range indices.
///
/// **These are the raw on-disk codes**, sentinels masked into `mask` and
/// nothing else applied — this calls `decode_variable_raw`. It does *not*
/// mirror the GRIB `decode_grid` surface, which its doc claimed until #664:
/// `decode_grid` returns a renderable field in the parameter's own units, and a
/// packed CF variable comes back here as integer codes. The CF mask-and-scale
/// is applied at the render seam instead (`unpack_cf_data`, #184/#186), which
/// is what `NetcdfHandle`'s entry points go through.
#[napi]
pub fn decode_netcdf_variable(
    bytes: napi::bindgen_prelude::Buffer,
    variable_index: u32,
) -> napi::Result<DecodedVariable> {
    let reader = NetcdfReader::from_bytes(bytes.to_vec()).into_napi()?;
    let raw = reader
        .decode_variable_raw(variable_index as usize)
        .into_napi()?;
    let shape = reader
        .variable_shape(variable_index as usize)
        .into_napi()?
        .into_iter()
        .map(|d| {
            u32::try_from(d)
                .map_err(|_| napi::Error::from_reason(format!("dimension length {d} exceeds u32")))
        })
        .collect::<napi::Result<Vec<u32>>>()?;

    let mut values = vec![0.0f64; raw.len()];
    let mut mask = vec![0u8; raw.len()];
    for (i, v) in raw.iter().enumerate() {
        match v {
            Some(x) => {
                values[i] = *x;
                mask[i] = 1;
            }
            None => values[i] = f64::NAN,
        }
    }
    Ok(DecodedVariable {
        values: napi::bindgen_prelude::Float64Array::new(values),
        mask: mask.into(),
        shape,
    })
}

